it('refuses an identity whose target the registry does not have, or that is not a production one', function (array $identity, string $reason) {
    $scratch = mailIdentityScratch();

    try {
        $files = mailIdentityFixtureConfig($scratch.'/config');
        $document = json_decode((string) file_get_contents($scratch.'/config/mail-identity.json'), true);
        $document['targets'] = [...$document['targets'], ...$identity];
        file_put_contents($scratch.'/config/mail-identity.json', mailRoutingJson($document));

        expectMailIdentityRefusal(mailIdentityRun(['validate', ...$files]), $reason);
    } finally {
        mailIdentityCleanup($scratch);
    }
})->with([
    'an unknown target' => [['food-guru' => mailIdentityDemoShopIdentity()], 'food-guru: not a target in the deployment registry'],
    'a staging target' => [['staging-main' => mailIdentityDemoShopIdentity()], 'staging-main: environment_class staging has no production mail identity — a staging target captures its mail and never signs it'],
    'a malformed target ID' => [['Demo_Shop' => mailIdentityDemoShopIdentity()], 'invalid target ID "Demo_Shop"'],
]);

it('refuses a DKIM selector that is not one safe lowercase DNS label', function (mixed $selector) {
    $scratch = mailIdentityScratch();

    try {
        $identity = mailIdentityDemoShopIdentity();
        $identity['dkim']['selector'] = $selector;

        expectMailIdentityRefusal(
            mailIdentityRun(['validate', ...mailIdentityFixtureConfig($scratch.'/config', ['identity' => $identity])]),
            'demo-shop: dkim.selector must be one lowercase DNS label',
        );
    } finally {
        mailIdentityCleanup($scratch);
    }
})->with([
    'uppercase' => 'RG1',
    'two labels' => 'rg1.mail',
    'an underscore' => 'rg_1',
    'a leading hyphen' => '-rg1',
    'a trailing hyphen' => 'rg1-',
    'empty' => '',
    'longer than a label' => str_repeat('a', 64),
    'whitespace' => 'rg 1',
    'a number' => 1,
]);

