});

// =============================================================================
// PRIVATE KEYS: JUDGED, NEVER SHOWN
// =============================================================================

it('accepts an unencrypted RSA private key of at least the reviewed size, PKCS#8 or PKCS#1', function (string $kind, int $bits) {
    $run = mailIdentityRun(['check-key', '--file', mailIdentityKey($kind)]);

    expect($run['status'])->toBe(0, $run['stderr']);
    expect($run['stdout'])->toContain("usable: an unencrypted {$bits}-bit RSA private key");
    expectNoKeyMaterial($run['stdout'].$run['stderr'], mailIdentityKey($kind));
})->with([
    'PKCS#8, 2048 bits' => ['rsa2048', 2048],
    'PKCS#1, 2048 bits' => ['rsa2048-pkcs1', 2048],
    'PKCS#8, 3072 bits' => ['rsa3072', 3072],
]);

it('refuses everything that is not a usable DKIM private key, without ever showing it', function (string $kind, string $reason) {
    $run = mailIdentityRun(['check-key', '--file', mailIdentityKey($kind)]);

    expectMailIdentityRefusal($run, "not a usable DKIM private key: {$reason}");
    expectNoKeyMaterial($run['stdout'].$run['stderr'], mailIdentityKey($kind));
})->with([
    'not PEM at all' => ['junk', 'it is not PEM'],
    'a public key' => ['public', 'it is a public key, not a private key'],
    'a certificate' => ['certificate', 'it is a certificate, not a private key'],
    'a key with a certificate beside it' => ['key-and-certificate', 'it is a certificate, not a private key'],
    'a passphrase-protected key' => ['encrypted', 'it is passphrase-protected'],
    'RSA below 2048 bits' => ['rsa1024', 'it is a 1024-bit RSA key, below the reviewed minimum of 2048 bits'],
    'an EC key' => ['ec', 'it is not a usable RSA private key'],
    'an Ed25519 key' => ['ed25519', 'it is not a usable RSA private key'],
]);

it('holds a key to the minimum the identity reviews, not merely to 2048 bits', function () {
    expectMailIdentityRefusal(
        mailIdentityRun(['check-key', '--file', mailIdentityKey('rsa2048'), '--min-bits', '3072']),
        'it is a 2048-bit RSA key, below the reviewed minimum of 3072 bits',
    );
    expect(mailIdentityRun(['check-key', '--file', mailIdentityKey('rsa3072'), '--min-bits', '3072'])['status'])->toBe(0);
});

it('refuses a key reached through a symlink, or that is not a regular file', function () {
    $scratch = mailIdentityScratch();

    try {
        symlink(mailIdentityKey('rsa2048'), $scratch.'/link.pem');

        expectMailIdentityRefusal(mailIdentityRun(['check-key', '--file', $scratch.'/link.pem']), 'it is a symlink');
        expectMailIdentityRefusal(mailIdentityRun(['check-key', '--file', $scratch.'/fs']), 'it is not a regular file');
        expectMailIdentityRefusal(mailIdentityRun(['check-key', '--file', $scratch.'/absent.pem']), 'it does not exist');
    } finally {
        mailIdentityCleanup($scratch);
    }
});

// =============================================================================
// THE DNS TO PUBLISH
// =============================================================================

it('prints exactly the records to publish, deriving the DKIM public key from the installed private key', function () {
    $scratch = mailIdentityScratch();

    try {
        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        $env = mailIdentityDnsHost($scratch, []);

        $run = mailIdentityRun(['show-dns', '--target', 'tits-guru'], $env);
        expect($run['status'])->toBe(0, $run['stderr']);

        $text = preg_replace('/\s+/', ' ', $run['stdout']);
        $public = mailIdentityPublicKey($key);

        expect($text)
            ->toContain('hostname mta1.tits.guru (direct delivery disabled on this host)')
            ->toContain('A mta1.tits.guru -> 203.0.113.10')
            ->toContain('PTR 203.0.113.10 -> mta1.tits.guru')
            ->toContain('TXT rg1._domainkey.tits.guru v=DKIM1; k=rsa; p='.$public)
            ->toContain('TXT tits.guru v=spf1 ip4:203.0.113.10 -all')
            ->toContain('TXT _dmarc.tits.guru v=DMARC1; p=none; adkim=s; aspf=s');

        expectNoKeyMaterial($run['stdout'].$run['stderr'], $key);

        // Deterministic: the same key and host print the same plan.
        expect(mailIdentityRun(['show-dns', '--target', 'tits-guru'], $env)['stdout'])->toBe($run['stdout']);
    } finally {
        mailIdentityCleanup($scratch);
    }
});

it('prints the same records as JSON, with nothing but public values', function () {
    $scratch = mailIdentityScratch();

    try {
        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        $run = mailIdentityRun(['show-dns', '--target', 'tits-guru', '--json'], mailIdentityDnsHost($scratch, []));

        expect($run['status'])->toBe(0, $run['stderr']);
        $plan = json_decode($run['stdout'], true, 512, JSON_THROW_ON_ERROR);

        expect($plan['mta'])->toBe(['direct_delivery_enabled' => false, 'hostname' => 'mta1.tits.guru', 'ipv4' => '203.0.113.10']);
        expect($plan['records'])->toBe([
            ['name' => 'mta1.tits.guru', 'type' => 'A', 'value' => '203.0.113.10'],
            ['name' => '203.0.113.10', 'type' => 'PTR', 'value' => 'mta1.tits.guru'],
            ['name' => 'rg1._domainkey.tits.guru', 'type' => 'TXT', 'value' => 'v=DKIM1; k=rsa; p='.mailIdentityPublicKey($key)],
            ['name' => 'tits.guru', 'type' => 'TXT', 'value' => 'v=spf1 ip4:203.0.113.10 -all'],
            ['name' => '_dmarc.tits.guru', 'type' => 'TXT', 'value' => 'v=DMARC1; p=none; adkim=s; aspf=s'],
        ]);

        expectNoKeyMaterial($run['stdout'], $key);
    } finally {
        mailIdentityCleanup($scratch);
    }
});

it('derives the public key from a key the operator holds, before it is installed anywhere', function () {
    // The order an operator works in: create the key, publish its public half,
    // then supply it. show-dns reads a key file named on the command line and
    // still prints only the public half.
    $scratch = mailIdentityScratch();

    try {
        $run = mailIdentityRun(['show-dns', '--target', 'tits-guru', '--key', mailIdentityKey('rsa2048-pkcs1'), '--ipv4', '198.51.100.7']);

        expect($run['status'])->toBe(0, $run['stderr']);
        expect(preg_replace('/\s+/', ' ', $run['stdout']))
            ->toContain('p='.mailIdentityPublicKey(mailIdentityKey('rsa2048')))
            ->toContain('v=spf1 ip4:198.51.100.7 -all');
        expectNoKeyMaterial($run['stdout'].$run['stderr'], mailIdentityKey('rsa2048-pkcs1'));
    } finally {
        mailIdentityCleanup($scratch);
    }
});

it('says what is still pending instead of inventing a key or an address', function () {
    $scratch = mailIdentityScratch();

    try {
        $run = mailIdentityRun(['show-dns', '--target', 'tits-guru'], mailIdentityDnsHost($scratch, [], null));

        expect($run['status'])->toBe(0, $run['stderr']);
        expect($run['stdout'])
            ->toContain('<pending: the installed key /etc/opendkim/keys/tits-guru/rg1.private is not usable — it does not exist>')
            ->toContain('<this host IPv4: run on the mail host, or pass --ipv4>')
            ->not->toContain('v=DKIM1');

        // A weak key is named as such, and never published.
        mailIdentityInstallKey($scratch, 'tits-guru', 'rg1', 'rsa1024');
        expect(mailIdentityRun(['show-dns', '--target', 'tits-guru'], mailIdentityDnsHost($scratch, []))['stdout'])
            ->toContain('below the reviewed minimum of 2048 bits')
            ->not->toContain('v=DKIM1; k=rsa; p=');

        expectMailIdentityRefusal(mailIdentityRun(['show-dns', '--target', 'staging-main']), 'staging-main has no mail identity');
    } finally {
        mailIdentityCleanup($scratch);
    }
});

// =============================================================================
// VERIFYING PUBLIC DNS
// =============================================================================

it('verifies correctly published DNS, joining a long DKIM record a provider split into chunks', function () {
    $scratch = mailIdentityScratch();

    try {
        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        $dns = mailIdentityGoodDns(mailIdentityPublicKey($key));

        // Proof the record really is split, with whitespace between the chunks.
        expect(substr_count($dns['TXT rg1._domainkey.tits.guru'][0], '" "'))->toBeGreaterThan(0);

        $run = mailIdentityRun(['verify-dns', '--target', 'tits-guru'], mailIdentityDnsHost($scratch, $dns));

        expect($run['status'])->toBe(0, $run['stdout'].$run['stderr']);
        expect($run['stdout'])
            ->toContain('PASS   a          mta1.tits.guru A includes this host\'s address 203.0.113.10')
            ->toContain('PASS   ptr        203.0.113.10 PTR is mta1.tits.guru')
            ->toContain('PASS   spf        tits.guru SPF authorizes exactly this host (203.0.113.10) and fails everything else')
            ->toContain('PASS   dkim       rg1._domainkey.tits.guru publishes exactly the public key of the installed private key')
            ->toContain('PASS   dmarc      _dmarc.tits.guru publishes exactly the reviewed policy')
            ->toContain('DNS VERIFIED: YES');
        expectNoKeyMaterial($run['stdout'].$run['stderr'], $key);
    } finally {
        mailIdentityCleanup($scratch);
    }
});

it('accepts a DKIM value a DNS panel published with whitespace inside the key, as verifiers do', function () {
    // RFC 6376 lets the base64 in p= carry folding whitespace, and some DNS
    // panels insert spaces into a long value; a verifier ignores them.
    $scratch = mailIdentityScratch();

    try {
        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        $dns = mailIdentityGoodDns(mailIdentityPublicKey($key));
        $dns['TXT rg1._domainkey.tits.guru'] = ['"v=DKIM1;  k=rsa ;  p='.implode(' ', str_split(mailIdentityPublicKey($key), 64)).'"'];

        $run = mailIdentityRun(['verify-dns', '--target', 'tits-guru'], mailIdentityDnsHost($scratch, $dns));

        expect($run['status'])->toBe(0, $run['stdout']);
        expect($run['stdout'])->toContain('PASS   dkim       rg1._domainkey.tits.guru publishes exactly the public key of the installed private key');
    } finally {
        mailIdentityCleanup($scratch);
    }
});

it('refuses every way public DNS can disagree with the reviewed identity', function (array $changes, string|false|null $ipv4, string $check, string $reason) {
    $scratch = mailIdentityScratch();

    try {
        $key = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1');
        $dns = mailIdentityGoodDns(mailIdentityPublicKey($key));

        // Each change replaces one answer whole; null removes it, and
        // OTHER_KEY stands for the public key of a different private key.
        foreach ($changes as $question => $answer) {
            if ($answer === null) {
                unset($dns[$question]);

                continue;
            }

            $dns[$question] = array_map(
                static fn (mixed $value): mixed => is_string($value) ? str_replace('OTHER_KEY', mailIdentityPublicKey(mailIdentityKey('rsa3072')), $value) : $value,
                $answer,
            );
        }

        $run = mailIdentityRun(
            ['verify-dns', '--target', 'tits-guru'],
            mailIdentityDnsHost($scratch, $dns, $ipv4 === false ? '203.0.113.10' : $ipv4),
        );

        expect($run['status'])->not->toBe(0, $run['stdout']);
        expect($run['stdout'])
            ->toMatch('/^  FAIL   '.preg_quote($check, '/').' +.*'.preg_quote($reason, '/').'/m')
            ->toContain('DNS VERIFIED: NO')
            ->not->toContain('DNS VERIFIED: YES');
        expectNoKeyMaterial($run['stdout'].$run['stderr'], $key);
    } finally {
        mailIdentityCleanup($scratch);
    }
})->with([
    'an A record elsewhere' => [['A mta1.tits.guru' => ['198.51.100.9']], false, 'a', 'mta1.tits.guru A is [198.51.100.9], which does not include this host\'s address 203.0.113.10'],
    'no A record' => [['A mta1.tits.guru' => null], false, 'a', 'mta1.tits.guru has no A record (NXDOMAIN)'],
    'a PTR naming something else' => [['PTR 10.113.0.203.in-addr.arpa' => ['ip-203-0-113-10.provider.example.']], false, 'ptr', '203.0.113.10 PTR is ip-203-0-113-10.provider.example, not mta1.tits.guru'],
    'no PTR' => [['PTR 10.113.0.203.in-addr.arpa' => null], false, 'ptr', '203.0.113.10 has no PTR record'],
    'two PTR records' => [['PTR 10.113.0.203.in-addr.arpa' => ['mta1.tits.guru.', 'other.example.']], false, 'ptr', 'has 2 PTR records'],
    'two SPF policies' => [['TXT tits.guru' => ['"v=spf1 ip4:203.0.113.10 -all"', '"v=spf1 include:_spf.provider.example ~all"']], false, 'spf', 'tits.guru publishes 2 SPF policies — receivers treat more than one as a permanent error'],
    'no SPF policy' => [['TXT tits.guru' => ['"site-verification=abc123"']], false, 'spf', 'tits.guru publishes no SPF policy — publish exactly one TXT record: v=spf1 ip4:203.0.113.10 -all'],
    'a soft-failing SPF' => [['TXT tits.guru' => ['"v=spf1 ip4:203.0.113.10 ~all"']], false, 'spf', 'tits.guru SPF is "v=spf1 ip4:203.0.113.10 ~all", not the reviewed'],
    'SPF for another address' => [['TXT tits.guru' => ['"v=spf1 ip4:198.51.100.9 -all"']], false, 'spf', 'not the reviewed "v=spf1 ip4:203.0.113.10 -all"'],
    'a DKIM record for another key' => [['TXT rg1._domainkey.tits.guru' => ['"v=DKIM1; k=rsa; p=OTHER_KEY"']], false, 'dkim', 'publishes a different public key than the installed private key derives'],
    'no DKIM record' => [['TXT rg1._domainkey.tits.guru' => null], false, 'dkim', 'rg1._domainkey.tits.guru has no TXT record'],
    'a DKIM record of another key type' => [['TXT rg1._domainkey.tits.guru' => ['"v=DKIM1; k=ed25519; p=abc"']], false, 'dkim', 'rg1._domainkey.tits.guru has k=ed25519, not k=rsa'],
    'a DKIM record in testing mode' => [['TXT rg1._domainkey.tits.guru' => ['"v=DKIM1; t=y; k=rsa; p=abc"']], false, 'dkim', 'must carry exactly the tags v, k and p, found: k p t v'],
    'two DKIM records' => [['TXT rg1._domainkey.tits.guru' => ['"v=DKIM1; k=rsa; p=OTHER_KEY"', '"v=DKIM1; k=rsa; p=abc"']], false, 'dkim', 'has 2 TXT records — a selector publishes exactly one key'],
    'a rejecting DMARC policy' => [['TXT _dmarc.tits.guru' => ['"v=DMARC1; p=reject; adkim=s; aspf=s"']], false, 'dmarc', '_dmarc.tits.guru has p=reject, not the reviewed p=none'],
    'relaxed DKIM alignment' => [['TXT _dmarc.tits.guru' => ['"v=DMARC1; p=none; adkim=r; aspf=s"']], false, 'dmarc', 'has adkim=r, not the reviewed adkim=s'],
    'a report address nobody reviewed' => [['TXT _dmarc.tits.guru' => ['"v=DMARC1; p=none; adkim=s; aspf=s; rua=mailto:x@tits.guru"']], false, 'dmarc', 'must carry exactly v, p, adkim and aspf'],
    'two DMARC policies' => [['TXT _dmarc.tits.guru' => ['"v=DMARC1; p=none; adkim=s; aspf=s"', '"v=DMARC1; p=none"']], false, 'dmarc', 'publishes 2 DMARC policies — exactly one is allowed'],
    'no DMARC policy' => [['TXT _dmarc.tits.guru' => null], false, 'dmarc', '_dmarc.tits.guru publishes no DMARC policy — publish exactly: v=DMARC1; p=none; adkim=s; aspf=s'],
    'a resolver that never answers' => [['TXT tits.guru' => ['exit' => 9]], false, 'spf', 'the DNS query for tits.guru TXT failed (dig exit 9)'],
    'a server failure' => [['TXT _dmarc.tits.guru' => ['status' => 'SERVFAIL']], false, 'dmarc', 'the DNS query for _dmarc.tits.guru TXT was answered SERVFAIL'],
    'a refused query' => [['A mta1.tits.guru' => ['status' => 'REFUSED']], false, 'a', 'was answered REFUSED'],
    'a host behind NAT' => [[], '10.0.0.5', 'address', 'this host sends from 10.0.0.5, which is not a public address'],
    'a host with no route' => [[], null, 'address', 'this host has no IPv4 route to the Internet'],
]);

it('cannot pass without a usable installed key, whatever DNS says', function () {
    $scratch = mailIdentityScratch();

    try {
        $dns = mailIdentityGoodDns(mailIdentityPublicKey(mailIdentityKey('rsa2048')));

        // Absent.
        $run = mailIdentityRun(['verify-dns', '--target', 'tits-guru'], mailIdentityDnsHost($scratch, $dns));
        expect($run['status'])->not->toBe(0);
        expect($run['stdout'])
            ->toContain('FAIL   key        the DKIM private key /etc/opendkim/keys/tits-guru/rg1.private is not usable: it does not exist')
            ->toContain('there is no valid installed private key to compare it with');

        // Too weak, even with a record that matches it.
        $weak = mailIdentityInstallKey($scratch, 'tits-guru', 'rg1', 'rsa1024');
        $dns['TXT rg1._domainkey.tits.guru'] = ['"v=DKIM1; k=rsa; p='.mailIdentityPublicKey($weak).'"'];
        $run = mailIdentityRun(['verify-dns', '--target', 'tits-guru'], mailIdentityDnsHost($scratch, $dns));
        expect($run['status'])->not->toBe(0);
        expect($run['stdout'])->toContain('below the reviewed minimum of 2048 bits')->toContain('DNS VERIFIED: NO');
    } finally {
        mailIdentityCleanup($scratch);
    }
});

